SELECT COUNT(*) FROM NOTIFICATION
WHERE MEMBER_NO = #{memberNo}
  AND NOTIFICATION_TYPE = #{notificationType}
  AND NOTIFICATION_LINK = #{notificationLink}

SELECT *
FROM (
         SELECT n.*, ROWNUM rnum
         FROM (
                  SELECT *
                  FROM NOTIFICATION
                  WHERE MEMBER_NO = #{memberNo}
                  ORDER BY CREATED_AT DESC
              ) n
         WHERE ROWNUM <= #{cPage} * #{numPerPage}
     )
WHERE rnum > (#{cPage}-1) * #{numPerPage}

SELECT COUNT(*) FROM NOTIFICATION
WHERE MEMBER_NO = #{memberNo}
  AND IS_READ = 'N'

mapper.update:
UPDATE NOTIFICATION
SET IS_READ = 'Y', READ_AT = SYSTIMESTAMP
WHERE NOTIFICATION_ID = #{notificationId}
